# credentials_app — the member's wallet

The holder side of the membership system. The wallet asks the issuer for a membership credential,
keeps it on the device next to the holder's key, and lists what it holds.

## Credentials

Credentials are **JWT-VCs**: the issuer signs a compact JWT whose `vc` claim carries the
credential, and the wallet keeps that token exactly as issued. The holder is identified by a
`did:key` (Ed25519, via the `ssi` package), created the first time the wallet needs it.

## Layout

| File | What it does |
|---|---|
| `lib/src/wallet_service.dart` | `WalletService` — holder key, credential requests, presentations |
| `lib/src/issuer_client.dart` | `IssuerClient` — the call to the issuer service (inject your own) |
| `lib/src/credential_store.dart` | `CredentialStore` — held credentials and the holder key |
| `lib/src/held_credential.dart` | `HeldCredential` — a credential as the wallet holds it |
| `lib/src/holder_key.dart` | `HolderKey` — the Ed25519 key and its `did:key` |
| `lib/src/presentation_request.dart` | `PresentationRequest` — an incoming OpenID4VP-style request |
| `lib/src/credential_list.dart` | `WalletScreen` / `CredentialList` — the wallet UI |

## Tests

```
flutter test
```

Tests run headless with a fake issuer client and fixture credentials; nothing touches the network.
/// Holder wallet: requests credentials from an issuer, keeps them with the
/// holder's did:key, and answers presentation requests.
library;

export 'src/credential_list.dart';
export 'src/credential_store.dart';
export 'src/held_credential.dart';
export 'src/holder_key.dart';
export 'src/issuer_client.dart';
export 'src/presentation_request.dart';
export 'src/wallet_service.dart';
import 'package:flutter/material.dart';

import 'held_credential.dart';
import 'wallet_service.dart';

class CredentialList extends StatelessWidget {
  const CredentialList({super.key, required this.credentials});

  final List<HeldCredential> credentials;

  @override
  Widget build(BuildContext context) {
    if (credentials.isEmpty) {
      return const Center(child: Text('No credentials yet'));
    }
    return ListView(
      children: [
        for (final credential in credentials)
          ListTile(
            leading: const Icon(Icons.badge_outlined),
            title: Text(credential.type),
            subtitle: Text(credential.issuer),
          ),
      ],
    );
  }
}

class WalletScreen extends StatefulWidget {
  const WalletScreen({super.key, required this.wallet});

  final WalletService wallet;

  @override
  State<WalletScreen> createState() => _WalletScreenState();
}

class _WalletScreenState extends State<WalletScreen> {
  bool _busy = false;

  Future<void> _requestMembership() async {
    setState(() => _busy = true);
    try {
      await widget.wallet.requestCredential('MembershipCredential');
    } on Exception catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Could not add credential: $e')));
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Wallet')),
      body: CredentialList(credentials: widget.wallet.heldCredentials()),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _busy ? null : _requestMembership,
        icon: const Icon(Icons.add),
        label: const Text('Request membership'),
      ),
    );
  }
}
import 'held_credential.dart';
import 'holder_key.dart';

/// In-memory wallet storage: held credentials by id, and the holder key.
class CredentialStore {
  final Map<String, HeldCredential> _credentials = {};

  void save(HeldCredential credential) =>
      _credentials[credential.id] = credential;

  HeldCredential? byId(String id) => _credentials[id];

  List<HeldCredential> all() => List.unmodifiable(_credentials.values);

  HolderKey? holderKey;
}
/// One salted claim the holder can reveal: its digest sits in the credential.
class Disclosure {
  const Disclosure({
    required this.salt,
    required this.name,
    required this.value,
  });

  factory Disclosure.fromJson(Object? json) {
    if (json is Map<String, dynamic>) {
      return Disclosure(
        salt: json['salt'] as String,
        name: json['name'] as String,
        value: json['value'],
      );
    }
    if (json is List && json.length == 3) {
      return Disclosure(
        salt: json[0] as String,
        name: json[1] as String,
        value: json[2],
      );
    }
    throw FormatException('Unrecognised disclosure: $json');
  }

  final String salt;
  final String name;
  final Object? value;

  Map<String, dynamic> toJson() => {'salt': salt, 'name': name, 'value': value};
}

/// A credential in the wallet: the issuer-signed document plus the
/// disclosures that go with it.
class HeldCredential {
  HeldCredential({required this.vc, required this.disclosures});

  /// Parses the issuer's response: `{"credential": {...}, "disclosures": [...]}`.
  factory HeldCredential.fromIssuance(Map<String, dynamic> json) {
    final vc = json['credential'];
    if (vc is! Map<String, dynamic>) {
      throw const FormatException('Issuance response has no credential');
    }
    final disclosures = (json['disclosures'] as List? ?? const [])
        .map(Disclosure.fromJson)
        .toList();
    return HeldCredential(vc: vc, disclosures: disclosures);
  }

  final Map<String, dynamic> vc;
  final List<Disclosure> disclosures;

  String get id => vc['id'] as String;

  String get issuer {
    final issuer = vc['issuer'];
    return issuer is Map ? issuer['id'] as String : issuer as String;
  }

  String? get holderDid =>
      (vc['credentialSubject'] as Map<String, dynamic>?)?['id'] as String?;

  /// The most specific type, e.g. `MembershipCredential`.
  String get type {
    final types = vc['type'];
    return types is List ? types.last as String : types as String;
  }

  Map<String, dynamic> toJson() => {
    'credential': vc,
    'disclosures': disclosures.map((d) => d.toJson()).toList(),
  };
}
import 'dart:typed_data';

import 'package:ssi/ssi.dart';

/// The holder's signing key and the did:key derived from it.
class HolderKey {
  HolderKey._(this.keyPair) : did = DidKey.getDid(keyPair.publicKey);

  /// A fresh random Ed25519 key.
  factory HolderKey.generate() {
    final (keyPair, _) = Ed25519KeyPair.generate();
    return HolderKey._(keyPair);
  }

  /// A key restored from its 32-byte seed.
  factory HolderKey.fromSeed(Uint8List seed) =>
      HolderKey._(Ed25519KeyPair.fromSeed(seed));

  final Ed25519KeyPair keyPair;
  final String did;

  /// The verification method id inside the did:key document.
  String get keyId => '$did#${did.substring('did:key:'.length)}';

  Future<Uint8List> sign(List<int> data) =>
      keyPair.sign(Uint8List.fromList(data));

  Future<bool> verify(List<int> data, List<int> signature) =>
      keyPair.verify(Uint8List.fromList(data), Uint8List.fromList(signature));
}
import 'held_credential.dart';

/// Talks to the issuer service.
abstract interface class IssuerClient {
  /// Asks the issuer for a [credentialType] credential about [holderDid].
  Future<HeldCredential> issue({
    required String holderDid,
    required String credentialType,
  });
}
import 'package:dcql/dcql.dart';

/// A verifier's request for a presentation, in the OpenID4VP shape:
/// who is asking (`client_id`), a `nonce`, and a DCQL query.
class PresentationRequest {
  const PresentationRequest({
    required this.clientId,
    required this.nonce,
    required this.dcqlQuery,
    this.responseUri,
  });

  factory PresentationRequest.fromJson(Map<String, dynamic> json) {
    final clientId = json['client_id'];
    final nonce = json['nonce'];
    final query = json['dcql_query'];
    if (clientId is! String || clientId.isEmpty) {
      throw const FormatException('Presentation request has no client_id');
    }
    if (nonce is! String || nonce.isEmpty) {
      throw const FormatException('Presentation request has no nonce');
    }
    if (query is! Map<String, dynamic>) {
      throw const FormatException('Presentation request has no dcql_query');
    }
    final responseUri = json['response_uri'];
    return PresentationRequest(
      clientId: clientId,
      nonce: nonce,
      dcqlQuery: DcqlCredentialQuery.fromJson(query),
      responseUri: responseUri is String ? Uri.parse(responseUri) : null,
    );
  }

  final String clientId;
  final String nonce;
  final DcqlCredentialQuery dcqlQuery;
  final Uri? responseUri;

  /// The domain a presentation for this request is addressed to.
  String get domain => clientId;

  Map<String, dynamic> toJson() => {
    'client_id': clientId,
    'nonce': nonce,
    'dcql_query': dcqlQuery.toJson(),
    if (responseUri != null) 'response_uri': responseUri.toString(),
  };
}
import 'credential_store.dart';
import 'held_credential.dart';
import 'holder_key.dart';
import 'issuer_client.dart';
import 'presentation_request.dart';

class WalletException implements Exception {
  const WalletException(this.message);
  final String message;
  @override
  String toString() => 'WalletException: $message';
}

/// The wallet's operations: holder key, credential requests, presentations.
class WalletService {
  WalletService({
    required this._issuer,
    CredentialStore? store,
    HolderKey Function()? newKey,
  }) : _store = store ?? CredentialStore(),
       _newKey = newKey ?? HolderKey.generate;

  final IssuerClient _issuer;
  final CredentialStore _store;
  final HolderKey Function() _newKey;

  /// The holder key, created on first use.
  HolderKey holderKey() => _store.holderKey ??= _newKey();

  /// Requests a [credentialType] credential for this holder and keeps it.
  Future<HeldCredential> requestCredential(String credentialType) async {
    final did = holderKey().did;
    final credential = await _issuer.issue(
      holderDid: did,
      credentialType: credentialType,
    );
    if (credential.holderDid != did) {
      throw WalletException(
        'Credential ${credential.id} was issued to ${credential.holderDid}, not $did',
      );
    }
    _store.save(credential);
    return credential;
  }

  List<HeldCredential> heldCredentials() => _store.all();

  HeldCredential? credential(String id) => _store.byId(id);

  /// Builds a presentation of the held credential [credentialId] in answer
  /// to [request], ready to send to the requester.
  Future<Map<String, dynamic>> createPresentation(
    String credentialId,
    PresentationRequest request,
  ) async {
    throw UnimplementedError('createPresentation');
  }
}
